// 3. Simulate rapid events (like scrolling)
console.log("Starting rapid scroll simulation...");

// These calls will only result in one execution immediately, and then one execution
// after 1 second has passed since the *last* execution.
throttledScroll({ type: 'scroll', x: 10 });
